<?php namespace App\Models; use Illuminate\Database\Eloquent\Model; class ContentAsset extends Model{protected $guarded=[]; protected $casts=['publish_date'=>'date']; public function tenant(){return $this->belongsTo(Tenant::class);} public function topic(){return $this->belongsTo(Topic::class);} public function channel(){return $this->belongsTo(Channel::class);} public function campaigns(){return $this->belongsToMany(Campaign::class,'campaign_asset');} public static function types(){return ['article'=>'Artikel','social_post'=>'Social Post','newsletter'=>'Newsletter','pdf'=>'PDF','landingpage'=>'Landingpage','video'=>'Video','event'=>'Event','other'=>'Sonstiges'];} public static function reusable(){return ['yes'=>'Ja','maybe'=>'Vielleicht','no'=>'Nein'];}}
